"""Minimal category-selecting frontend; uses cached exact nearest-category route costs."""
from pathlib import Path
import os,json,re,gzip,base64
ROOT=Path(__file__).resolve().parents[1];CITY_MODE=os.environ.get('EMPATH_CITY_MODE')=='1';OUT=ROOT/('output/plano_city/accessibility' if CITY_MODE else 'output/block_accessibility')

def run():
 source=(OUT/'block_accessibility_map.html').read_text();payload=json.loads(re.search(r'const DATA=(.*?);const map=',source,re.S).group(1))
 routing_meta=OUT/'routing_network_method.json'
 payload['routingVersion']=json.loads(routing_meta.read_text())['sha256'] if routing_meta.exists() else 'current'
 payload['city_mode']=CITY_MODE
 county=ROOT/'output/collin_county/county_boundary.geojson'
 county_blocks_path=ROOT/'output/collin_county/county_census_blocks.gpkg'
 if county_blocks_path.exists():
  import geopandas as gpd
  cb=gpd.read_file(county_blocks_path)[['GEOID20','geometry']].to_crs(26914)
  cb.geometry=cb.geometry.simplify(5,preserve_topology=True)
  payload['county_blocks']=base64.b64encode(gzip.compress(cb.to_crs(4326).to_json(drop_id=True).encode())).decode()
 else:payload['county_blocks']=''
 payload['county']=base64.b64encode(gzip.compress(county.read_bytes())).decode() if county.exists() else ''
 html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EmPath · Choose your walking needs</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>
*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui;color:#183c35;background:#f3f5f0}.layout{display:grid;grid-template-columns:350px 1fr;height:100dvh}aside{padding:24px;overflow:auto;border-right:1px solid #d4dfd8;background:#fafcf9}h1{font:40px Georgia;margin:0}h2{font-size:18px;margin:22px 0 9px}p{margin:8px 0 15px}.eyebrow{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#52695e}a{color:#185b47}button,select{font:inherit;border:1px solid #b9cfc0;border-radius:7px;padding:8px;background:white;color:#183c35;cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #e69d35;outline-offset:2px}button.primary{background:#185b47;color:white}.buttons{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.categories label{display:flex;align-items:center;gap:10px;padding:6px 0}.categories input{width:18px;height:18px;accent-color:#185b47}#map{height:100%;min-height:400px}.notice{font-size:12px;padding:12px;background:#fff3db;border-left:3px solid #d59422;border-radius:5px}.subtle{font-size:12px;color:#52695e}.legend{background:white;padding:12px;max-width:300px;border-radius:7px;box-shadow:0 1px 5px #999;font:13px system-ui}.ramp{height:12px;background:linear-gradient(90deg,#2166ac,#67a9cf,#ffffbf,#ef8a62,#b2182b);margin:6px 0}table{border-collapse:collapse;font-size:12px}th,td{padding:5px;border-bottom:1px solid #ddd;text-align:left}.leaflet-popup-content{max-height:420px;overflow:auto}#summary{padding:12px;background:#e5eee3;border-radius:7px;font-size:13px}#share-message{font-size:12px;overflow-wrap:anywhere}#county-notice{display:none;margin-top:10px}#scope{width:100%}@media(max-width:760px){.layout{grid-template-columns:1fr;grid-template-rows:45dvh 55dvh}aside{border-right:0;border-bottom:1px solid #ccc;padding:16px}.categories{display:grid;grid-template-columns:1fr 1fr;gap:0 8px}h1{font-size:32px}#map{min-height:0}}</style></head><body><div class="layout"><aside><div class="eyebrow">Pedestrian accessibility · prototype</div><h1>EmPath</h1><p>What do you need to reach on foot?</p><p class="subtle">Select service categories. Each block finds the lowest-friction candidate in each selected category, then averages those trip costs.</p><label for="scope"><strong>Study area</strong></label><select id="scope"><option value="pilot">Four Plano ZIP areas · scored</option><option value="county">Collin County · expansion preview</option></select><div id="county-notice" class="notice">County boundary and all 16,324 Census blocks are available. Only the existing four-ZIP pilot has computed accessibility. Outside the pilot is unscored, not low-cost. Countywide routes and environmental inputs still need processing.</div><h2>Choose service categories</h2><div class="buttons"><button id="essential" class="primary">Temple + grocery + pharmacy</button><button id="all">All</button><button id="clear">Clear</button></div><div id="categories" class="categories"></div><div id="summary" aria-live="polite">Loading saved routing results…</div><div class="buttons"><button id="share">Copy this selection’s link</button><button id="download">Download block scores</button></div><div id="share-message" aria-live="polite"></div><p><a href="index.html">All project maps</a> · <a href="method.html">Scoring equation</a> · <a href="validation.html">Evaluation</a></p><div class="notice"><strong>Decision support, not validated navigation.</strong> Estimated heat, traffic and tree context; equal category weights. Block/POI entrances and crossings are unverified. Snap gaps and incomplete destination coverage can affect rankings.</div></aside><main id="map" aria-label="Walking accessibility choropleth"></main></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const DATA=__DATA__;const map=L.map('map',{preferCanvas:true,scrollWheelZoom:true});L.tileLayer('https://empathmaps.netlify.app/.netlify/functions/basemap?z={z}&x={x}&y={y}',{attribution:'© OpenStreetMap contributors · © CARTO',maxZoom:20}).addTo(map);const el=id=>document.getElementById(id);const esc=v=>String(v??'Unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=v=>v==null?'Unknown':Number(v).toFixed(1);const labels={church:'Churches',mosque:'Mosques / masjids',synagogue:'Synagogues',buddhist_temple:'Buddhist temples',gurdwara:'Sikh gurdwaras',other_worship:'Other / unspecified places of worship',beauty_supply:'Beauty & hair supply stores',cosmetics:'Cosmetics stores',gym:'Gyms (membership may apply)',bank:'Banks',recreation_centre:'Recreation centers',swimming_pool:'Pools (eligibility varies)',sports_centre:'Sports centers',hindu_temple:'Hindu temples (candidate catalog)',supermarket:'Grocery stores / supermarkets',pharmacy:'Pharmacies',bus_station:'Bus stations',station:'Rail stations',community_centre:'Community centers',convenience:'Convenience stores',clinic:'Clinics',college:'Colleges',hospital:'Hospitals',library:'Libraries',park:'Parks',playground:'Playgrounds',school:'Schools'};const palette=['#2166ac','#67a9cf','#ffffbf','#ef8a62','#b2182b'];const color=v=>v==null?'#adb5bd':palette[Math.min(4,Math.floor(Math.max(0,Math.min(99.999,v))/20))];
async function unpack(s){const a=Uint8Array.from(atob(s),c=>c.charCodeAt(0));return JSON.parse(await new Response(new Blob([a]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}
function quantile(sorted,p){const i=(sorted.length-1)*p;const lo=Math.floor(i),hi=Math.ceil(i);return sorted[lo]+(sorted[hi]-sorted[lo])*(i-lo);}
function computeScores(features,lookup,selected){const rows={};const means=[];for(const f of features){const id=f.properties.GEOID20;const choices=selected.map(c=>lookup[id]?.[c]);const valid=selected.length>0&&choices.every(r=>r&&Number.isFinite(r.min_friction_equivalent_minutes));const mean=valid?choices.reduce((s,r)=>s+r.min_friction_equivalent_minutes,0)/selected.length:null;rows[id]={mean,sum:mean==null?null:mean*selected.length,reached:choices.filter(r=>r&&Number.isFinite(r.min_friction_equivalent_minutes)).length,score:null};if(mean!=null)means.push(mean);}means.sort((a,b)=>a-b);const lo=means.length?quantile(means,.02):null,hi=means.length?quantile(means,.98):null;for(const r of Object.values(rows))if(r.mean!=null)r.score=hi>lo?100*Math.max(0,Math.min(1,(r.mean-lo)/(hi-lo))):0;return{rows,lo,hi,complete:means.length};}
(async()=>{try{const[blocks,details,zones,pois,county]=await Promise.all([unpack(DATA.blocks),unpack(DATA.details),unpack(DATA.zones),unpack(DATA.pois),DATA.county?unpack(DATA.county):null]);const lookup={};for(const[id,rows]of Object.entries(details))lookup[id]=Object.fromEntries(rows.map(r=>[r.category,r]));const categories=[...new Set(Object.values(details).flatMap(rows=>rows.map(r=>r.category)))].sort((a,b)=>(labels[a]||a).localeCompare(labels[b]||b));let selected=['hindu_temple','supermarket','pharmacy'];const query=new URLSearchParams(location.search);if(query.has('categories'))selected=query.get('categories').split(',').filter(c=>categories.includes(c));let scores={rows:{}};for(const cat of categories){const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.value=cat;input.checked=selected.includes(cat);input.addEventListener('change',update);label.appendChild(input);label.appendChild(document.createTextNode(labels[cat]||cat));el('categories').appendChild(label);}
let countyBlocksLayer=null;let scopeToken=0;const countyLayer=county?L.geoJSON(county,{style:{color:'#555',weight:2,fillColor:'#c4c8cb',fillOpacity:.4},onEachFeature:(f,l)=>l.bindTooltip('Collin County · outside-pilot accessibility has not been calculated')}):null;
const boundary=L.geoJSON(zones,{style:{color:'#34486e',weight:1.5,fill:false}}).addTo(map);
const layer=L.geoJSON(blocks,{style:f=>({color:'#657078',weight:.35,fillColor:color(scores.rows[f.properties.GEOID20]?.score),fillOpacity:.85}),onEachFeature:(f,l)=>{const p=f.properties;l.bindTooltip(()=>'<b>Block '+esc(p.GEOID20)+'</b><br>Mean category trip: '+fmt(scores.rows[p.GEOID20]?.mean)+' equivalent min');l.bindPopup(()=>{const r=scores.rows[p.GEOID20];return '<b>Block '+esc(p.GEOID20)+'</b><br>'+esc(p.representative_address)+'<br>Relative accessibility burden: '+fmt(r?.score)+' / 100<br>Average closest-category cost: '+fmt(r?.mean)+' equivalent min<br>Combined cost: '+fmt(r?.sum)+' equivalent min<br>Reached: '+(r?.reached||0)+'/'+selected.length+' categories<br>Block reference-point snap gap: '+fmt(p.access_snap_gap_m)+' m'+(p.access_connection_needs_review?' · REVIEW':'')+'<hr><table><tr><th>Category</th><th>Lowest-cost candidate</th><th>Equiv. min</th></tr>'+selected.map(c=>{const d=lookup[p.GEOID20]?.[c];return '<tr><td>'+esc(labels[c]||c)+'</td><td>'+esc(d?.closest_poi_name)+'</td><td>'+fmt(d?.min_friction_equivalent_minutes)+'</td></tr>';}).join('')+'</table><hr><small>Lowest cost among current catalog candidates, not every real service. Network-only cost; access connectors and crossing waits excluded. Equal assumed category weights.</small>';},{maxWidth:530});}}).addTo(map);
window.empathContext={map,blocks,lookup,pois,layer,labels,routingVersion:DATA.routingVersion};const poiGroup=L.layerGroup().addTo(map);const legend=L.control({position:'bottomright'});legend.onAdd=()=>{const d=L.DomUtil.create('div','legend');d.id='legend';return d;};legend.addTo(map);
function update(){selected=[...el('categories').querySelectorAll('input:checked')].map(x=>x.value);scores=computeScores(blocks.features,lookup,selected);layer.setStyle(f=>({color:'#657078',weight:.35,fillColor:color(scores.rows[f.properties.GEOID20].score),fillOpacity:.85}));layer.closePopup();poiGroup.clearLayers();for(const f of pois.features){const p=f.properties;if(!selected.includes(p.category))continue;const[lng,lat]=f.geometry.coordinates;L.circleMarker([lat,lng],{radius:p.category==='hindu_temple'?6:4,color:'white',weight:1,fillColor:'#ed8a24',fillOpacity:1}).bindPopup('<b>'+esc(p.name)+'</b><br>'+esc(labels[p.category]||p.category)+'<br>'+esc(p.address_status)).addTo(poiGroup);}el('summary').textContent=selected.length?`${selected.length} categories selected · ${scores.complete.toLocaleString()} / ${blocks.features.length.toLocaleString()} blocks reach every selected category.`:'Select at least one category to calculate accessibility.';el('legend').innerHTML='<b>Accessibility burden</b><div class="ramp"></div>Blue: lower costs → red: higher<br>Gray: incomplete selected-category access<br><small>Relative colors rescale for each selection.<br>2nd–98th percentile costs: '+fmt(scores.lo)+'–'+fmt(scores.hi)+' equivalent minutes.<br>Compare raw minutes across selections.</small>';const params=new URLSearchParams();params.set('categories',selected.join(','));params.set('scope',el('scope').value==='county'?'county':DATA.city_mode?'city':'pilot');try{history.replaceState(null,'','?'+params);}catch{}window.empathSelection={categories:selected,scores};window.dispatchEvent(new CustomEvent('empath-selection-changed'));}
function preset(cats){for(const input of el('categories').querySelectorAll('input'))input.checked=cats.includes(input.value);update();}
el('essential').onclick=()=>preset(['hindu_temple','supermarket','pharmacy']);el('all').onclick=()=>preset(categories);el('clear').onclick=()=>preset([]);
async function changeScope(){const token=++scopeToken;const countyMode=el('scope').value==='county';el('county-notice').style.display=countyMode?'block':'none';if(countyLayer){if(countyMode){if(!countyBlocksLayer&&DATA.county_blocks){const countyData=await unpack(DATA.county_blocks);if(token!==scopeToken)return;countyBlocksLayer=L.geoJSON(countyData,{style:{color:'#8a9298',weight:.35,fillColor:'#c4c8cb',fillOpacity:.35},onEachFeature:(f,l)=>l.bindTooltip('County block '+esc(f.properties.GEOID20)+' · outside-pilot access is not calculated')});}if(countyBlocksLayer){countyBlocksLayer.addTo(map);countyBlocksLayer.bringToBack();}countyLayer.addTo(map);countyLayer.bringToBack();map.fitBounds(countyLayer.getBounds());}else{map.removeLayer(countyLayer);if(countyBlocksLayer)map.removeLayer(countyBlocksLayer);}}if(!countyMode)map.fitBounds(boundary.getBounds());update();}
el('scope').onchange=changeScope;if(query.get('scope')==='county')el('scope').value='county';changeScope();
el('share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);el('share-message').textContent='Selection link copied.';}catch{el('share-message').textContent=location.href;}};
el('download').onclick=()=>{const lines=['GEOID20,selected_categories,mean_equivalent_minutes,sum_equivalent_minutes,relative_burden_0_100,reached_categories,origin_snap_gap_m'];for(const f of blocks.features){const p=f.properties,r=scores.rows[p.GEOID20];lines.push([p.GEOID20,selected.join('|'),r.mean??'',r.sum??'',r.score??'',r.reached,p.access_snap_gap_m].join(','));}const url=URL.createObjectURL(new Blob([lines.join('\\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='empath-selected-block-scores.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}catch(e){el('summary').textContent='Could not load the prototype. Try a current browser. '+e.message;}})();</script></body></html>'''
 html=html.replace('__DATA__',json.dumps(payload));html=html.replace('</body>','<script src="routes.js"></script><script src="context.js"></script><script src="boundary.js"></script></body>')
 if CITY_MODE:
  html=html.replace('Four Plano ZIP areas · scored','City of Plano · scored').replace('Only the existing four-ZIP pilot has computed accessibility.','Only the Plano city scope has computed accessibility.').replace('Outside the pilot is unscored','Outside the city scope is unscored').replace('outside-pilot access','outside-city access')
 (OUT/'empath_category_selector.html').write_text(html.replace('href="index.html"','href="https://empathmaps.netlify.app/"').replace('href="method.html"','href="https://empathmaps.netlify.app/method.html"'))
 (ROOT/'netlify_site/src/app.html').write_text(html)
 return ROOT/'netlify_site/src/app.html'
if __name__=='__main__':print(run())
